import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, color } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // Create the plane geometry (512x320 px → ~2.13x1.33 scene units at standard scale)
  const width = 2.13;
  const height = 1.33;
  const geometry = new THREE.PlaneGeometry(width, height);

  // Load and apply the texture
  const material = new MeshBasicNodeMaterial();
  material.colorNode = color(0xffffff);

  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    material.colorNode = uv().mul(vec3(1.0)).mul(color(tex));
    material.map = tex;
    material.needsUpdate = true;
  });

  const plane = new THREE.Mesh(geometry, material);

  // Apply scene position (adapter will use this)
  if (config.scenePosition) {
    plane.position.copy(config.scenePosition);
  }

  // Create text overlay for "Features 1"
  const textContent = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textItem = textContent.find((item) => item.role === 'headline');

  const group = new THREE.Group();
  group.add(plane);

  if (textItem) {
    const text = ctx.fontAtlas.createText(textItem.text, {
      fontSize: textItem.typography?.fontSize ?? 39,
      color: '#e8ecf2',
      align: 'left',
    });
    text.position.set(-width * 0.45, height * 0.35, 0.01);
    group.add(text);
  }

  // Cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
  };

  group.userData.handlers = {};

  return group;
}
